//! Compatibility tests against the fixture generated by the Go implementation.

use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use pm_netstate::{ProcFs, Stack, UNDEFINED_PROCESS_ID};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/netstate.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn temp_dir(tag: &str) -> PathBuf {
    let mut path = std::env::temp_dir();
    path.push(format!(
        "pm-netstate-{tag}-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .subsec_nanos()
    ));
    let _ = std::fs::remove_dir_all(&path);
    std::fs::create_dir_all(&path).unwrap();
    path
}

fn add_socket_owner(root: &Path, pid: i32, inode: i64) {
    let fd_dir = root.join(pid.to_string()).join("fd");
    std::fs::create_dir_all(&fd_dir).unwrap();
    let target = format!("socket:[{inode}]");
    let _ = std::os::unix::fs::symlink(target, fd_dir.join("7"));
}

#[test]
fn proc_tables_match_go() {
    let fixture = fixture();
    let tables = fixture["tables"].as_array().unwrap();
    assert_eq!(tables.len(), 4);

    let mut total_connections = 0;
    let mut total_binds = 0;

    for table in tables {
        let stack = match table["stack"].as_str().unwrap() {
            "tcp4" => Stack::Tcp4,
            "tcp6" => Stack::Tcp6,
            "udp4" => Stack::Udp4,
            "udp6" => Stack::Udp6,
            other => panic!("unknown stack {other}"),
        };

        if let Some(error) = table.get("error").and_then(Value::as_str) {
            // The Go side could not read the table; nothing to compare.
            assert!(!error.is_empty());
            continue;
        }

        let raw = table["raw"].as_str().unwrap();
        let (connections, binds) = pm_netstate::proc::parse_table(stack, raw);

        let expected_connections = table["connections"].as_array().unwrap();
        assert_eq!(
            connections.len(),
            expected_connections.len(),
            "connection count for {stack:?}"
        );
        for (got, want) in connections.iter().zip(expected_connections) {
            assert_eq!(
                got.local.ip.to_string(),
                want["local_ip"].as_str().unwrap(),
                "{stack:?}"
            );
            assert_eq!(
                u64::from(got.local.port),
                want["local_port"].as_u64().unwrap(),
                "{stack:?}"
            );
            assert_eq!(
                got.remote.ip.to_string(),
                want["remote_ip"].as_str().unwrap(),
                "{stack:?}"
            );
            assert_eq!(
                u64::from(got.remote.port),
                want["remote_port"].as_u64().unwrap(),
                "{stack:?}"
            );
            assert_eq!(i64::from(got.uid), want["uid"].as_i64().unwrap());
            assert_eq!(got.inode, want["inode"].as_i64().unwrap());
        }

        let expected_binds = table["binds"].as_array().unwrap();
        assert_eq!(
            binds.len(),
            expected_binds.len(),
            "bind count for {stack:?}"
        );
        for (got, want) in binds.iter().zip(expected_binds) {
            assert_eq!(
                got.local.ip.to_string(),
                want["local_ip"].as_str().unwrap(),
                "{stack:?}"
            );
            assert_eq!(
                u64::from(got.local.port),
                want["local_port"].as_u64().unwrap(),
                "{stack:?}"
            );
            assert_eq!(i64::from(got.uid), want["uid"].as_i64().unwrap());
            assert_eq!(got.inode, want["inode"].as_i64().unwrap());
            assert_eq!(got.listens_any, got.local.ip.is_unspecified());
        }

        total_connections += connections.len();
        total_binds += binds.len();
    }

    assert!(
        total_connections > 0,
        "fixture contains live TCP connections"
    );
    assert!(total_binds > 0, "fixture contains live binds");
}

#[test]
fn pid_lookup_matches_go() {
    let fixture = fixture();
    let lookup = fixture["pid_lookup"].as_object().unwrap();
    let uid = lookup["uid"].as_i64().unwrap() as i32;
    let inode = lookup["inode"].as_i64().unwrap();
    let pid = lookup["pid"].as_i64().unwrap() as i32;

    let root = temp_dir("pid");
    let current_uid = std::fs::metadata(&root).unwrap().uid() as i32;
    if current_uid != uid {
        // The generator ran as another user; its PID table keys do not apply.
        eprintln!("skipping: fixture uid {uid} != current uid {current_uid}");
        return;
    }

    // A decoy process owns a different socket.
    add_socket_owner(&root, pid + 1, inode + 1);
    add_socket_owner(&root, pid, inode);

    let procfs = ProcFs::new(&root);
    assert_eq!(procfs.find_pid(uid, inode), pid);
    assert_eq!(procfs.find_pid(uid, inode + 1), pid + 1);

    // Unknown inodes and unknown users are not found.
    assert_eq!(procfs.find_pid(uid, inode + 2), UNDEFINED_PROCESS_ID);
    assert_eq!(procfs.find_pid(uid + 1, inode), UNDEFINED_PROCESS_ID);

    // The owner is cached but revalidated against the PID list.
    assert_eq!(procfs.find_pid(uid, inode), pid);
}
